import{_ as e,c as r,o as t,af as o}from"./chunks/framework.r60quYNK.js";const p=JSON.parse('{"title":"长沙 - 2024","description":"","frontmatter":{},"headers":[],"relativePath":"2_articles/travel_record/ChangSha.md","filePath":"2_articles/travel_record/ChangSha.md"}'),h={name:"2_articles/travel_record/ChangSha.md"};function i(l,a,n,d,c,_){return t(),r("div",null,a[0]||(a[0]=[o('<h1 id="长沙-2024" tabindex="-1">长沙 - 2024 <a class="header-anchor" href="#长沙-2024" aria-label="Permalink to &quot;长沙 - 2024&quot;">​</a></h1><h2 id="_5月1日-5月4日-🌦️" tabindex="-1">5月1日 - 5月4日 🌦️ <a class="header-anchor" href="#_5月1日-5月4日-🌦️" aria-label="Permalink to &quot;5月1日 - 5月4日 🌦️&quot;">​</a></h2><blockquote><p>一年一度五一之旅，此篇以黛黛视角来写，看看我们的写法有什么不一样的地方哈哈！</p></blockquote><h3 id="前言" tabindex="-1">前言 <a class="header-anchor" href="#前言" aria-label="Permalink to &quot;前言&quot;">​</a></h3><p>又到了异地长假见面的日子，这次本来打算还是选择中间一座城市，结果实在不知道还有哪个好玩了，索性就选在了离我近的长沙——黛黛一直很想去的地方。</p><h3 id="_4月30日" tabindex="-1">4月30日 <a class="header-anchor" href="#_4月30日" aria-label="Permalink to &quot;4月30日&quot;">​</a></h3><p>我出发啦，先高铁到郑州凌晨一点中转去长沙，当时很饿在站外点了正新鸡排 谁知道那个大肉串如此长，给我都吃笑啦！杜离得近点 他坐了第二天一早的高铁和我汇合（每次旅行都是他比我早到比我晚回“接送我”）</p><h3 id="_5月1日" tabindex="-1">5月1日 <a class="header-anchor" href="#_5月1日" aria-label="Permalink to &quot;5月1日&quot;">​</a></h3><p>中午汇合后去了酒店，在长沙理工对面 由于很累啦就点了外卖先填饱肚子。下午就去了五一广场、国金中心，吃了正宗的长沙臭豆腐，可能是地域问题觉得确实比家里那边的好吃哈哈哈。因为知道长沙是“银都”于是俩人在坡子街准备diy戒指，一看价格吓跑了，后来在街口发现了和大人走散的小孩，就把他交给了警察蜀黍（当时俩人很期待被夸）。后来在购物广场里拍了大头贴，之后心血来潮去沃尔玛买小火锅食材回去自己煮火锅吃辣（可能是逛不习惯 感觉食材太不好买了哈哈哈之后回去看到酒店附近居然有菜市场！！）。</p><h3 id="_5月2日" tabindex="-1">5月2日 <a class="header-anchor" href="#_5月2日" aria-label="Permalink to &quot;5月2日&quot;">​</a></h3><p>一早我俩提着在酒店门口买的《杭州》小笼包赶地铁去橘子洲头啦，人巨巨巨巨多排到两眼发黑，好不容易等到小火车还要抢着上，后来在人群中拍了很多好看的照片。在橘子洲还和我姐以及她对象汇合啦，我们一起拍了照片！后来去岳麓山的时候我俩走到脚疼腿软 好不容易到了结果排队超级长无奈返回，最后找到了返程地铁站又又又是排队！（晚上才知道我姐和对象俩人坐了轮渡去的那边！我俩真是大冤种）。晚上我们去了杜甫江阁，半路还在水果摊尝到了马蹄，后来和姐姐他们相汇了，返程她也想尝马蹄结果老板娘没有那个意思了哈哈哈哈，之后他俩请客我们一起吃了绿草地（湘菜）蛮好吃的喔！后面我们坐地铁回酒店啦（才知道人俩天天住在五一广场附近，他俩真是一点不委屈自己）</p><h3 id="_5月3日" tabindex="-1">5月3日 <a class="header-anchor" href="#_5月3日" aria-label="Permalink to &quot;5月3日&quot;">​</a></h3><p>不出意外依然起的很晚，而且下的雨很大，想到我们俩的伞小小的就临时在留下便利店买了把很贵得伞。早上（中午）吃了塔斯汀，去了湖南省博物馆，看到了辛追夫人之墓蛮震惊的。之后我们去吃了八一桥米粉（本地人好多但真的好难好难找），去了太平老街杜杜给我拍了好看的照片。后面跟着小红书的攻略去了长沙超级文和友（还得感谢海底捞的小姐姐给指的路呢）。准备打道回府了在路上还看到了排了百米长队的零食很大，还有安保在旁边！杜杜还说给我买个超大奥利奥扛回去哈哈哈哈哈。然后俩人又想喝点小酒吃点烧烤了 顺便品鉴一下长沙小龙虾，就在酒店附近买了1元一只的麻小回去狂欢啦！（这里巨搞笑，回去我说想喝点热饮，杜杜点喝的直接脱口而出：一杯辣的茉莉奶绿哈哈哈哈哈给我笑到爆）</p><h3 id="_5月4日" tabindex="-1">5月4日 <a class="header-anchor" href="#_5月4日" aria-label="Permalink to &quot;5月4日&quot;">​</a></h3><p>又是一天分别日啦，感觉没有地方可以逛啦就搜了搜一些景点准备去古开福寺以及2号没去成的岳麓山。早上吃了小碗菜（不咋滴哈哈哈），然后去了古开福寺，很幸运遇到一对情侣让我们帮他俩拍合照，拍完本想让他俩用我们的相机帮拍结果直接送了我俩一次拍立得，当时激动坏了人生第一张和杜杜的拍立得，俩人爱不释手，那时候想拥有拍立得的心达到了顶峰，后来杜杜就买给我啦（宝贝mini99），有求必应哦。在这里我俩分别利用罗汉签抽到了自己的人生指引（杜杜后来经过夏令营的洗礼彻底悟透了自己的签，我也通过坚持不懈得到了好结果）。之后我们去了湖南大学（那所地铁站在校园里面的大学）没想到四大书院之一的岳麓书院是人家们读书的地方，震惊三连！！！后面打卡了停车坐爱枫林晚霜叶红于二月花的爱晚亭，蛮有意境的。在这里你还能看到共享自行车停在山上hiahiahia！返程就快到点回学校啦，结束呀我们才找到了万家丽广场，在这边吃了第一顿韩餐部队火锅（当时人超多生怕赶不到车站），杜杜还给我买了特色点心麻薯很不错！返程时在石家庄中转，杜为了让我睡卧铺直接从贵阳开始买的他一直有在兼职赚钱不让我在站票啦！不出意外离别还是很伤感，都给我哭懵了进站直接走错了检票口想想还是很好笑，后面杜杜也坐了晚上的高铁回去啦！（没想到分别这一天是旅行效率最高的，好吧之前都是我起不来）</p><p>我们的旅行又一次结束啦，就像你看到的，他给我画的饼不管是拍立得还是南京发誓以后不让我站票出行他都一一实现啦！我们很幸福希望看到这里的你和你们也要一直幸福开心哦！</p><p><code>最后更新时间：2025-09-18 22:37:36</code></p>',17)]))}const u=e(h,[["render",i]]);export{p as __pageData,u as default};
